CREATE OR REPLACE VIEW public.colab_v_parties AS SELECT p.* FROM public.parties p WHERE NOT (SELECT public.colab_restrita()) OR p.id IN (SELECT party_id FROM public.consultant_profiles WHERE representative_party_id=(SELECT public.colab_rep()));
CREATE OR REPLACE VIEW public.colab_v_consultant_profiles AS SELECT cp.* FROM public.consultant_profiles cp WHERE NOT (SELECT public.colab_restrita()) OR cp.representative_party_id=(SELECT public.colab_rep());
CREATE OR REPLACE VIEW public.colab_v_party_roles AS SELECT p.* FROM public.party_roles p WHERE NOT (SELECT public.colab_restrita()) OR p.party_id IN (SELECT party_id FROM public.colab_v_consultant_profiles);
CREATE OR REPLACE VIEW public.colab_v_contact_points AS SELECT p.* FROM public.contact_points p WHERE NOT (SELECT public.colab_restrita()) OR p.party_id IN (SELECT party_id FROM public.colab_v_consultant_profiles);
CREATE OR REPLACE VIEW public.colab_v_party_addresses AS SELECT p.* FROM public.party_addresses p WHERE NOT (SELECT public.colab_restrita()) OR p.party_id IN (SELECT party_id FROM public.colab_v_consultant_profiles);
CREATE OR REPLACE VIEW public.colab_v_legado_representantes AS SELECT lr.* FROM public.legado_representantes lr WHERE NOT (SELECT public.colab_restrita()) OR lr.party_id=(SELECT public.colab_rep());
CREATE OR REPLACE VIEW public.colab_v_legado_pracas AS SELECT lp.* FROM public.legado_pracas lp WHERE NOT (SELECT public.colab_restrita()) OR lp.codigo IN (SELECT unnest(lr.pracas) FROM public.legado_representantes lr WHERE lr.party_id=(SELECT public.colab_rep()));
CREATE OR REPLACE VIEW public.colab_v_legado_remessas AS SELECT r.* FROM public.legado_remessas r WHERE NOT (SELECT public.colab_restrita()) OR r.representante IN (SELECT codigo FROM public.colab_v_legado_representantes);
CREATE OR REPLACE VIEW public.colab_v_legado_maletas AS SELECT m.* FROM public.legado_maletas m WHERE NOT (SELECT public.colab_restrita()) OR m.remessa IN (SELECT numero FROM public.colab_v_legado_remessas);
CREATE OR REPLACE VIEW public.colab_v_legado_consultoras AS SELECT c.* FROM public.legado_consultoras c WHERE NOT (SELECT public.colab_restrita()) OR c.codcli IN (SELECT codcli FROM public.colab_v_legado_maletas);
DO $ddl$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['legado_maleta_categorias','legado_maleta_vendidos','legado_notas','legado_acertos_consultora','legado_maleta_status'] LOOP EXECUTE format('CREATE OR REPLACE VIEW public.colab_v_%I AS SELECT m.* FROM public.%I m WHERE NOT (SELECT public.colab_restrita()) OR m.remessa IN (SELECT numero FROM public.colab_v_legado_remessas)',t,t); END LOOP; END $ddl$;
CREATE OR REPLACE VIEW public.colab_v_legado_acertos_praca AS SELECT a.* FROM public.legado_acertos_praca a WHERE NOT (SELECT public.colab_restrita()) OR a.representante IN (SELECT codigo FROM public.colab_v_legado_representantes);
CREATE OR REPLACE VIEW public.colab_v_remessas AS SELECT r.* FROM public.remessas r WHERE NOT (SELECT public.colab_restrita()) OR r.representante_party_id=(SELECT public.colab_rep());
CREATE OR REPLACE VIEW public.colab_v_cob_pracas AS SELECT p.* FROM public.cob_pracas p WHERE NOT (SELECT public.colab_restrita()) OR p.id IN (SELECT praca_id FROM public.colab_v_legado_pracas);
CREATE OR REPLACE VIEW public.colab_v_kit_cycles AS SELECT c.* FROM public.kit_cycles c WHERE NOT (SELECT public.colab_restrita()) OR c.representante_party_id=(SELECT public.colab_rep()) OR c.remessa_id IN (SELECT id FROM public.colab_v_remessas);
DO $ddl$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.catalog_overview()'::regprocedure) INTO d; d:=replace(d,'BEGIN',E'BEGIN\n IF public.colab_restrita() THEN RAISE EXCEPTION ''Visão geral de estoque indisponível para colaboradora.'' USING errcode=''42501''; END IF;'); EXECUTE d; END $ddl$;